function PacketHandlers:S2CSetMonsterYaw(packet)
    local entity = EntityCache:getEntityByServerId(packet.entityId)
    if entity and entity.entity then
        entity.entity:setPositionAndRotation2(entity.entity:getPosition(), packet.yaw, 0, 5)
    end
end

function PacketHandlers:ShowMonsterEffect(packet)
    local entity = EntityCache:getEntityByServerId(packet.entityId)
    if entity then
        entity:setShowEffect(packet.effectName)
    end
end

function PacketHandlers:SetMonsterSimpleEffect(packet)
    local entity = EntityCache:getEntityByServerId(packet.entityId)
    if entity then
        entity:setSimpleEffect(packet.effectData)
    end
end

local function addWallText(data)
    local globalRender = Blockman.Instance().m_globalRender
    globalRender:luaAddWallText(data.type, data.time or 0, data.text, data.pos, data.scale or 1, data.yaw or 0, data.pitch or 0, Color.WHITE)
end

local function delWallText(data)
    local globalRender = Blockman.Instance().m_globalRender
    globalRender:deleteWallText(data.pos, 0.001)
end

function PacketHandlers:showSceneTimeText(packet)
    if packet.isShow then
        addWallText(packet.data)
    else
        delWallText(packet.data)
    end
end